            >
              <div
                style={{
                  width: '100%',
                  height: '100%',
                  background: GIORGIA.signal,
                  transform: `scaleX(${progress})`,
                  transformOrigin: 'left center',
                  transition: 'transform 140ms linear'
                }}
              />
            </div>
          ) : null}
