            {message}
          </h1>
          <p className="text-xl text-text-secondary dark:text-text-secondary mb-8">
            {details}
          </p>
          {stack && (
            <pre className="w-full p-4 overflow-x-auto bg-white/50 rounded-lg text-left text-sm">
              <code>{stack}</code>
            </pre>
          )}
        </div>
      </main>
    </div>
  );
}

