interface SongPayload {
  id?: string;
  artist: string;
  title: string;
  coverUrl: string;
  audioUrl?: string;
  durationMs?: number;
  earoneSongId?: string;
  earoneRank?: string;
  earoneSpins?: string;
}

function toSingleSongSequence(song: SongPayload): ProgramSongSequence {
  const itemId = [
    song.id?.trim() || '',
    song.artist.trim(),
    song.title.trim(),
    song.audioUrl?.trim() || '',
    song.coverUrl.trim(),
    song.earoneSongId?.trim() || ''
  ]
    .filter(Boolean)
    .join('|');
  return {
    mode: 'manual',
    items: [
      {
        id: itemId,
        kind: 'preset',
        artist: song.artist,
        title: song.title,
        coverUrl: song.coverUrl,
        audioUrl: song.audioUrl,
        durationMs: song.durationMs,
        earoneSongId: song.earoneSongId,
        earoneRank: song.earoneRank,
        earoneSpins: song.earoneSpins
      }
    ],
    activeItemId: itemId,
    intervalMs: 4000,
    loop: true,
    startedAt: 0
  };
}

function shuffleArray<T>(items: T[]): T[] {
  const next = [...items];
  for (let i = next.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [next[i], next[j]] = [next[j], next[i]];
  }
  return next;
}

function formatClockValue(timezone: string, now: Date, timeOverride: GlobalTimeOverride | null): string {
  if (timeOverride) {
    const parts = getOverrideClockParts(timeOverride, now);
    if (parts) {
      return `${String(parts.hours).padStart(2, '0')}:${String(parts.minutes).padStart(2, '0')}`;
    }
  }

  try {
    return now.toLocaleTimeString('en-GB', {
      timeZone: timezone,
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    });
  } catch {
    return now.toLocaleTimeString('en-GB', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    });
  }
}

function normalizeSongPayload(value: unknown): SongPayload | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return null;
  }

  const record = value as Record<string, unknown>;
  const artist = typeof record.artist === 'string' ? record.artist.trim() : '';
  const title = typeof record.title === 'string' ? record.title.trim() : '';
  const coverUrl = typeof record.coverUrl === 'string' ? record.coverUrl.trim() : '';
  const audioUrl = typeof record.audioUrl === 'string' ? record.audioUrl.trim() : '';
  const durationMs =
    typeof record.durationMs === 'number' && Number.isFinite(record.durationMs) && record.durationMs > 0 ? Math.round(record.durationMs) : undefined;
  const earoneSongId =
    typeof record.earoneSongId === 'string' && record.earoneSongId.trim()
      ? record.earoneSongId.trim()
      : typeof record.earoneSongId === 'number' && Number.isFinite(record.earoneSongId)
        ? String(record.earoneSongId)
        : undefined;
  const earoneRank = typeof record.earoneRank === 'string' && record.earoneRank.trim() ? record.earoneRank.trim() : undefined;
  const earoneSpins =
    typeof record.earoneSpins === 'string' && record.earoneSpins.trim()
      ? record.earoneSpins.trim()
      : typeof record.earoneSpins === 'number' && Number.isFinite(record.earoneSpins)
        ? String(record.earoneSpins)
        : undefined;

  if (!artist && !title && !coverUrl && !audioUrl && !durationMs && !earoneSongId && !earoneRank && !earoneSpins) {
    return null;
  }

  return {
    artist,
    title,
    coverUrl,
    audioUrl: audioUrl || undefined,
    durationMs,
    earoneSongId,
    earoneRank,
    earoneSpins
  };
}

export const ModoItalianoClock: React.FC<ModoItalianoClockProps> = ({
  programId,
  timeOverride = null,
  rotationIntervalMs = 5000,
  transitionDurationMs = 300,
  shuffleCities = false,
  widthPx = 220,
  language = 'it',
  showWorldClocks = true,
  showBellIcon = false,
  showLogo = true,
  showPlaybackProgress = true,
  songs,
  songSequence,
  playingSong,
  songArtist = '',
  songTitle = '',
  songCoverUrl = '',
  songEaroneSongId = '',
  songEaroneRank = '',
  songEaroneSpins = '',
  inline = false
}) => {
  const resolvedCities = DEFAULT_MODOITALIANO_CLOCK_CITIES;
  const [now, setNow] = useState(() => new Date());
  const [cityPool, setCityPool] = useState<ModoItalianoClockCity[]>(() => (shuffleCities ? shuffleArray(resolvedCities) : [...resolvedCities]));
  const [cityIndex, setCityIndex] = useState(0);
  const [isFading, setIsFading] = useState(false);

  useEffect(() => {
    const timer = window.setInterval(() => {
      setNow(new Date());
    }, 1000);
    return () => window.clearInterval(timer);
  }, []);

  useEffect(() => {
    setCityPool(shuffleCities ? shuffleArray(resolvedCities) : [...resolvedCities]);
    setCityIndex(0);
    setIsFading(false);
  }, [resolvedCities, shuffleCities]);

  useEffect(() => {
    if (!showWorldClocks || cityPool.length <= 1) {
      return;
    }

    const rotateDelay = Math.max(500, rotationIntervalMs);
    const fadeDuration = Math.max(0, transitionDurationMs);
    let switchTimer: number | undefined;

    const interval = window.setInterval(() => {
      setIsFading(true);
      switchTimer = window.setTimeout(() => {
        setCityIndex((prevIndex) => {
          const nextIndex = prevIndex + 1;
          if (nextIndex >= cityPool.length) {
            setCityPool((prevPool) => (shuffleCities ? shuffleArray(prevPool) : prevPool));
            return 0;
          }
          return nextIndex;
        });
        setIsFading(false);
      }, fadeDuration);
    }, rotateDelay);

    return () => {
      window.clearInterval(interval);
      if (switchTimer !== undefined) {
        window.clearTimeout(switchTimer);
      }
    };
  }, [showWorldClocks, cityPool, rotationIntervalMs, transitionDurationMs, shuffleCities]);

  const currentCity = cityPool[cityIndex] ?? resolvedCities[0];
  const timeText = formatClockValue(currentCity.timezone, now, timeOverride);
  const normalizedSongSequence = useMemo(() => normalizeProgramSongSequence(songSequence), [songSequence]);
  const [sequenceNowMs, setSequenceNowMs] = useState(() => Date.now());
  const legacySongPayload = useMemo(() => {
    const directFromFields = normalizeSongPayload({
      artist: songArtist,
      title: songTitle,
      coverUrl: songCoverUrl,
      earoneSongId: songEaroneSongId,
      earoneRank: songEaroneRank,
      earoneSpins: songEaroneSpins
    });
    if (directFromFields) {
      return directFromFields;
    }

    if (!Array.isArray(songs)) {
      return null;
    }

    for (const song of songs) {
      const normalized = normalizeSongPayload(song);
      if (normalized) {
        return normalized;
      }
    }

    return null;
  }, [songArtist, songTitle, songCoverUrl, songEaroneSongId, songEaroneRank, songEaroneSpins, songs]);
  const effectiveSongSequence = useMemo(
    () => normalizedSongSequence ?? (legacySongPayload ? toSingleSongSequence(legacySongPayload) : null),
    [normalizedSongSequence, legacySongPayload]
  );
  const resolvedSequenceSong = useMemo(
    () =>
      resolveProgramSongLeaf(
        {
          sequence: effectiveSongSequence
        },
        sequenceNowMs
      ),
    [sequenceNowMs, effectiveSongSequence]
  );

  useEffect(() => {
    setSequenceNowMs(Date.now());
  }, [effectiveSongSequence]);

  useEffect(() => {
    if (!effectiveSongSequence || effectiveSongSequence.mode !== 'autoplay') {
      return;
    }

    const timer = window.setInterval(() => {
      setSequenceNowMs(Date.now());
    }, 250);

    return () => window.clearInterval(timer);
  }, [
    effectiveSongSequence?.mode,
    effectiveSongSequence?.startedAt,
    effectiveSongSequence?.intervalMs,
    effectiveSongSequence?.loop,
    effectiveSongSequence?.items.length
  ]);

  const activeSongPayload = resolvedSequenceSong;
  const [audioBusSnapshot, setAudioBusSnapshot] = useState(() => getProgramAudioBusSnapshot(programId));
  const fallbackSongArtist = activeSongPayload?.artist?.trim() || '';
  const fallbackSongTitle = activeSongPayload?.title?.trim() || '';
  const fallbackSongCoverUrl = activeSongPayload?.coverUrl?.trim() || '';
  const songGateEnabled = typeof playingSong === 'boolean' ? playingSong : true;
  const audioBusSong = songGateEnabled ? audioBusSnapshot.track : null;
  const normalizedSongArtist = (audioBusSong?.artist ?? fallbackSongArtist).trim();
  const normalizedSongTitle = (audioBusSong?.title ?? fallbackSongTitle).trim();
  const normalizedSongCoverUrl = (audioBusSong?.coverUrl ?? fallbackSongCoverUrl).trim();
  const hasSongPayload = songGateEnabled && (!!normalizedSongArtist || !!normalizedSongTitle);
  const hasLiveSongPayload = hasSongPayload && (!audioBusSong || audioBusSnapshot.endedToken !== audioBusSong.token);
  const [songUiVisible, setSongUiVisible] = useState(hasLiveSongPayload);
  const [songUiActive, setSongUiActive] = useState(hasLiveSongPayload);
  const [displaySongTitle, setDisplaySongTitle] = useState(normalizedSongTitle);
  const [displaySongArtist, setDisplaySongArtist] = useState(normalizedSongArtist);
  const [displaySongCoverUrl, setDisplaySongCoverUrl] = useState(normalizedSongCoverUrl || '/cover.jpg');
  const [clockBoxMotion, setClockBoxMotion] = useState<'in' | 'out' | null>(null);
  const previousHasSongPayloadRef = useRef(hasLiveSongPayload);
  const useSplitSongClockLayout = songUiVisible && (showWorldClocks || showLogo || showBellIcon);

  useEffect(() => {
    return subscribeProgramAudioBus(programId, (snapshot) => {
      setAudioBusSnapshot(snapshot);
    });
  }, [programId]);

  useEffect(() => {
    if (hasLiveSongPayload) {
      setDisplaySongTitle(normalizedSongTitle);
      setDisplaySongArtist(normalizedSongArtist);
      setDisplaySongCoverUrl(normalizedSongCoverUrl || '/cover.jpg');
    }
  }, [hasLiveSongPayload, normalizedSongTitle, normalizedSongArtist, normalizedSongCoverUrl]);

  useEffect(() => {
    const previousHasSongPayload = previousHasSongPayloadRef.current;
    previousHasSongPayloadRef.current = hasLiveSongPayload;

    let fadeTimer: number | undefined;
    let motionTimer: number | undefined;
    let frameHandle: number | undefined;

    if (hasLiveSongPayload) {
      setSongUiVisible(true);
      frameHandle = window.requestAnimationFrame(() => {
        setSongUiActive(true);
      });

      if (!previousHasSongPayload) {
        setClockBoxMotion('in');
        motionTimer = window.setTimeout(() => {
          setClockBoxMotion(null);
        }, SONG_BOX_MOTION_MS);
      }
    } else if (previousHasSongPayload) {
      setSongUiActive(false);
      setClockBoxMotion('out');
      fadeTimer = window.setTimeout(() => {
        setSongUiVisible(false);
        setDisplaySongTitle('');
        setDisplaySongArtist('');
        setDisplaySongCoverUrl('/cover.jpg');
      }, SONG_UI_FADE_MS);
      motionTimer = window.setTimeout(() => {
        setClockBoxMotion(null);
      }, SONG_BOX_MOTION_MS);
    }

    return () => {
      if (frameHandle !== undefined) {
        window.cancelAnimationFrame(frameHandle);
      }
      if (fadeTimer !== undefined) {
        window.clearTimeout(fadeTimer);
      }
      if (motionTimer !== undefined) {
        window.clearTimeout(motionTimer);
      }
    };
  }, [hasLiveSongPayload]);

  const logoBlock = (
    <div
      aria-label='MI'
      role='img'
      style={{
        width: '172px',
        height: '56px',
        background: 'rgba(255, 255, 255, 0.56)',
        WebkitMaskImage: "url('/mi.svg')",
        WebkitMaskRepeat: 'no-repeat',
        WebkitMaskPosition: 'center',
        WebkitMaskSize: 'contain',
        maskImage: "url('/mi.svg')",
        maskRepeat: 'no-repeat',
        maskPosition: 'center',
        maskSize: 'contain'
      }}
    />
  );

  if (!showWorldClocks && !showBellIcon && !showLogo) {
    return null;
  }

  // Logo-only mode when clocks are hidden and no song UI is active
  if (!showWorldClocks && !showBellIcon && showLogo && !songUiVisible) {
    return (
      <div
        style={
          inline
            ? { display: 'flex', flexDirection: 'column', width: 'fit-content' }
            : { position: 'absolute', top: '64px', right: '96px', zIndex: 950 }
        }
      >
        {logoBlock}
      </div>
    );
  }
  const wrapperStyle: React.CSSProperties = inline
    ? {
        display: 'flex',
        flexDirection: 'column',
        width: useSplitSongClockLayout ? '100%' : 'fit-content'
      }
    : {
        position: 'absolute',
        top: '64px',
        right: '96px',
        zIndex: 950,
        display: 'flex',
        flexDirection: 'column',
        width: useSplitSongClockLayout ? 'min(1420px, calc(100vw - 192px))' : 'fit-content'
      };
  const listeningStyle: React.CSSProperties = {
    color: '#ffffff',
    fontFamily: "'Outfit', 'Encode Sans', system-ui, sans-serif",
    fontSize: '38.4px',
    fontWeight: 500,
    lineHeight: 1,
    textAlign: 'left',
    textShadow: '0 4px 18px rgba(0, 0, 0, 0.96), 0 0 28px rgba(0, 0, 0, 0.72), 0 0 10px rgba(255, 255, 255, 0.2)',
    WebkitTextStroke: '0.7px rgba(0, 0, 0, 0.5)',
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    paddingLeft: '34px'
  };
  const listeningRowStyle: React.CSSProperties = {
    marginBottom: '18px',
    display: 'flex',
    alignItems: 'flex-end',
    justifyContent: 'space-between',
    gap: '16px',
    paddingRight: '34px',
    opacity: songUiActive ? 1 : 0,
    transform: songUiActive ? 'translateY(0px)' : 'translateY(10px)',
    transition: `opacity ${SONG_UI_FADE_MS}ms ease, transform ${SONG_UI_FADE_MS}ms ease`
  };
  const coverStyle: React.CSSProperties = {
    width: '198px',
    height: '198px',
    borderRadius: '12px',
    objectFit: 'cover',
    boxShadow: '0 10px 24px rgba(0, 0, 0, 0.55)',
    flexShrink: 0
  };
  const hasSongCardBackground = songUiVisible;
  const clockBoxMotionAnimation =
    clockBoxMotion === 'in'
      ? `, modoItalianoClockSongBoxIn ${SONG_BOX_MOTION_MS}ms cubic-bezier(0.2, 0.8, 0.2, 1) 1`
      : clockBoxMotion === 'out'
        ? `, modoItalianoClockSongBoxOut ${SONG_BOX_MOTION_MS}ms cubic-bezier(0.2, 0.8, 0.2, 1) 1`
        : '';
  const outerStyle: React.CSSProperties = {
    height: '140px',
    borderRadius: '50px',
    background: hasSongCardBackground ? 'linear-gradient(125deg, #6B7E39 0%, #3F4D20 48%, #6B7E39 100%)' : 'transparent',
    backgroundSize: hasSongCardBackground ? '200% 200%' : undefined,
    display: 'flex',
    alignItems: 'center',
    justifyContent: useSplitSongClockLayout ? 'space-between' : 'flex-start',
    width: useSplitSongClockLayout ? '100%' : undefined,
    padding: '0 34px',
    boxShadow: hasSongCardBackground ? '0 24px 44px rgba(0, 0, 0, 0.72)' : 'none',
    filter: hasSongCardBackground ? 'drop-shadow(0 12px 24px rgba(0, 0, 0, 0.52))' : 'none',
    maxWidth: '100%',
    position: 'relative',
    overflow: 'hidden',
    transformOrigin: 'right center',
    animation: hasSongCardBackground
      ? `modoItalianoClockBgFlow 8s ease-in-out infinite${clockBoxMotionAnimation}`
      : clockBoxMotion
        ? `modoItalianoClockSongBox${clockBoxMotion === 'in' ? 'In' : 'Out'} ${SONG_BOX_MOTION_MS}ms cubic-bezier(0.2, 0.8, 0.2, 1) 1`
        : undefined
  };
  const clampedSongProgress = Math.max(0, Math.min(1, audioBusSong ? audioBusSnapshot.progress : 0));
  const progressLayerStyle: React.CSSProperties = {
    position: 'absolute',
    inset: 0,
    borderRadius: 'inherit',
    background: 'linear-gradient(90deg, rgba(255, 255, 255, 0.14) 0%, rgba(255, 255, 255, 0.08) 70%, rgba(255, 255, 255, 0.02) 100%)',
    transform: `scaleX(${clampedSongProgress})`,
    transformOrigin: 'left center',
    transition: 'transform 140ms linear, opacity 220ms ease',
    opacity: hasSongCardBackground && hasLiveSongPayload && showPlaybackProgress ? 1 : 0,
    pointerEvents: 'none'
  };
  const progressEdgeStyle: React.CSSProperties = {
    position: 'absolute',
    top: 0,
    bottom: 0,
    left: `${clampedSongProgress * 100}%`,
    width: '2px',
    background: 'rgba(255, 255, 255, 0.28)',
    boxShadow: '0 0 8px rgba(255, 255, 255, 0.22)',
    opacity: hasSongCardBackground && hasLiveSongPayload && showPlaybackProgress ? 1 : 0,
    transform: 'translateX(-1px)',
    transition: 'left 140ms linear, opacity 220ms ease',
    pointerEvents: 'none'
  };

  const cityLabel = currentCity.city.trim().toUpperCase();
  const clockBadgeText = `${timeText} ${cityLabel}`.trim();
  const cityClockBlock = (
    <div
      style={{
        minWidth: `${Math.max(160, widthPx)}px`,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        gap: '4px'
      }}
    >
      {logoBlock}
      <div
        style={{
          height: '62px',
          minWidth: `${Math.max(176, widthPx)}px`,
          borderRadius: '999px',
          background: 'rgba(255, 255, 255, 0.56)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '0 24px'
        }}
      >
        <span
          style={{
            color: '#1f1f1f',
            fontFamily: "'Outfit', 'Encode Sans', system-ui, sans-serif",
            fontSize: '38.4px',
            fontWeight: 600,
            lineHeight: 1,
            textAlign: 'center',
            whiteSpace: 'nowrap',
            fontVariantNumeric: 'tabular-nums',
            opacity: isFading ? 0.35 : 1,
            transition: 'opacity 220ms ease'
          }}
        >
          {clockBadgeText}
        </span>
      </div>
    </div>
  );

  return (
    <div style={wrapperStyle}>
      <style>{`
        @keyframes modoItalianoClockBgFlow {
          0% { background-position: 0% 50%; }
          50% { background-position: 100% 50%; }
          100% { background-position: 0% 50%; }
        }
        @keyframes modoItalianoClockRedOverlay {
          0% { opacity: 0; }
          50% { opacity: 1; }
          100% { opacity: 0; }
        }
        @keyframes modoItalianoClockSongBoxIn {
          0% { transform: scale(1); }
          60% { transform: scale(1.04); }
          100% { transform: scale(1); }
        }
        @keyframes modoItalianoClockSongBoxOut {
          0% { transform: scale(1); }
          60% { transform: scale(0.96); }
          100% { transform: scale(1); }
        }
      `}</style>
      {songUiVisible && (
        <div style={listeningRowStyle}>
          <div style={listeningStyle}>Estás escuchando:</div>
          <img src={displaySongCoverUrl} alt='Cover' style={coverStyle} />
        </div>
      )}
      <div style={outerStyle}>
        {hasSongCardBackground && (
          <div
            style={{
              position: 'absolute',
              inset: 0,
              borderRadius: 'inherit',
              background: 'linear-gradient(125deg, #A42323 0%, #661313 48%, #A42323 100%)',
              backgroundSize: '200% 200%',
              animation: 'modoItalianoClockBgFlow 8s ease-in-out infinite, modoItalianoClockRedOverlay 60s ease-in-out infinite',
              opacity: 0,
              zIndex: 0,
              pointerEvents: 'none'
            }}
          />
        )}
        <div style={progressLayerStyle} />
        <div style={progressEdgeStyle} />
        {songUiVisible && (
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              justifyContent: 'center',
              marginRight: '28px',
              flex: useSplitSongClockLayout ? '1 1 auto' : undefined,
              minWidth: useSplitSongClockLayout ? 0 : undefined,
              maxWidth: useSplitSongClockLayout ? undefined : '980px',
              opacity: songUiActive ? 1 : 0,
              transform: songUiActive ? 'translateY(0px)' : 'translateY(10px)',
              transition: `opacity ${SONG_UI_FADE_MS}ms ease, transform ${SONG_UI_FADE_MS}ms ease`,
              position: 'relative',
              zIndex: 1
            }}
          >
            {displaySongTitle ? (
              <div
                style={{
                  color: '#ffffff',
                  fontFamily: "'Barlow Condensed', 'Encode Sans', system-ui, sans-serif",
                  fontSize: '44px',
                  fontWeight: 600,
                  lineHeight: 1,
                  letterSpacing: '0.02em',
                  textTransform: 'uppercase',
                  whiteSpace: 'nowrap',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis'
                }}
              >
                {displaySongTitle}
              </div>
            ) : null}
            {displaySongArtist ? (
              <div
                style={{
                  marginTop: displaySongTitle ? '8px' : 0,
                  color: '#ffffff',
                  fontFamily: "'Barlow Condensed', 'Encode Sans', system-ui, sans-serif",
                  fontSize: '44px',
                  fontWeight: 500,
                  lineHeight: 1,
                  letterSpacing: '0.02em',
                  textTransform: 'uppercase',
                  whiteSpace: 'nowrap',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis'
                }}
              >
                {displaySongArtist}
              </div>
            ) : null}
          </div>
        )}
        {(showWorldClocks || showBellIcon || showLogo) && (
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              flexShrink: 0,
              marginLeft: useSplitSongClockLayout ? '24px' : 0,
              position: 'relative',
              zIndex: 1,
              gap: '20px'
            }}
          >
            {showWorldClocks && cityClockBlock}
            {!showWorldClocks && showLogo && logoBlock}
            {showBellIcon && (
              <div
                style={{
                  width: '72px',
                  height: '72px',
                  borderRadius: '24px',
                  background: '#3a3a3a',
                  color: '#f3f3f3',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}
              >
                <BellRing size={42} strokeWidth={2} />
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  normalizeProgramTextSequence,
  resolveProgramTextLeaf
} from '../utils/programSequence';

interface ModoItalianoChyronProps {
  show?: boolean;
  textSequence?: unknown;
  ctaSequence?: unknown;
  inline?: boolean;
}

const CHYRON_SWAP_MS = 220;

export const ModoItalianoChyron: React.FC<ModoItalianoChyronProps> = ({
  show = true,
  textSequence,
  ctaSequence,
  inline = false
}) => {
  const [nowMs, setNowMs] = useState(() => Date.now());
  const normalizedTextSequence = useMemo(
    () => normalizeProgramTextSequence(textSequence, 0, { includeMarquee: true }),
    [textSequence]
  );
  const normalizedCtaSequence = useMemo(
    () => normalizeProgramTextSequence(ctaSequence),
    [ctaSequence]
  );
  const shouldTick = normalizedTextSequence?.mode === 'autoplay' || normalizedCtaSequence?.mode === 'autoplay';

  useEffect(() => {
    if (!shouldTick) {
      return;
    }

    const timer = window.setInterval(() => {
      setNowMs(Date.now());
    }, 250);

    return () => window.clearInterval(timer);
  }, [
    shouldTick,
    normalizedTextSequence?.mode,
    normalizedTextSequence?.startedAt,
    normalizedTextSequence?.intervalMs,
    normalizedTextSequence?.loop,
    normalizedTextSequence?.items.length,
    normalizedCtaSequence?.mode,
    normalizedCtaSequence?.startedAt,
    normalizedCtaSequence?.intervalMs,
    normalizedCtaSequence?.loop,
    normalizedCtaSequence?.items.length
  ]);

  useEffect(() => {
    setNowMs(Date.now());
  }, [textSequence, ctaSequence]);

  const resolvedTextLeaf = resolveProgramTextLeaf(
    {
      contentMode: 'sequence',
      sequence: normalizedTextSequence
    },
    nowMs,
    { includeMarquee: true }
  );
  const resolvedCtaLeaf = resolveProgramTextLeaf(
    {
      contentMode: 'sequence',
      sequence: normalizedCtaSequence
    },
    nowMs
  );
  const resolvedMainText = resolvedTextLeaf?.text.trim() ?? '';
  const resolvedUseMarquee = Boolean(resolvedTextLeaf?.useMarquee);
  const resolvedCtaText = resolvedCtaLeaf?.text.trim() ?? '';

  const [displayMainText, setDisplayMainText] = useState(resolvedMainText);
  const [displayUseMarquee, setDisplayUseMarquee] = useState(resolvedUseMarquee);
  const [mainTextActive, setMainTextActive] = useState(true);
  const [displayCtaText, setDisplayCtaText] = useState(resolvedCtaText);
  const [ctaActive, setCtaActive] = useState(true);
  const shouldShowChyron = Boolean(show && resolvedMainText);
  const [isMounted, setIsMounted] = useState(shouldShowChyron);
  const [isVisible, setIsVisible] = useState(shouldShowChyron);
  const mainTextSwapTimerRef = useRef<number | null>(null);
  const ctaSwapTimerRef = useRef<number | null>(null);
  const visibilityTimerRef = useRef<number | null>(null);
  const visibilityFrameRef = useRef<number | null>(null);

  useEffect(() => {
    if (visibilityTimerRef.current !== null) {
      window.clearTimeout(visibilityTimerRef.current);
      visibilityTimerRef.current = null;
    }
    if (visibilityFrameRef.current !== null) {
      window.cancelAnimationFrame(visibilityFrameRef.current);
      visibilityFrameRef.current = null;
    }

    if (shouldShowChyron) {
      setIsMounted(true);
      visibilityFrameRef.current = window.requestAnimationFrame(() => {
        setIsVisible(true);
        visibilityFrameRef.current = null;
      });
      return;
    }

    setIsVisible(false);
    visibilityTimerRef.current = window.setTimeout(() => {
      setIsMounted(false);
      visibilityTimerRef.current = null;
    }, CHYRON_SWAP_MS);
  }, [shouldShowChyron]);

  useEffect(() => {
    if (resolvedMainText === displayMainText && resolvedUseMarquee === displayUseMarquee) {
      return;
    }

    if (mainTextSwapTimerRef.current !== null) {
      window.clearTimeout(mainTextSwapTimerRef.current);
      mainTextSwapTimerRef.current = null;
    }

    setMainTextActive(false);
    mainTextSwapTimerRef.current = window.setTimeout(() => {
      setDisplayMainText(resolvedMainText);
      setDisplayUseMarquee(resolvedUseMarquee);
      setMainTextActive(true);
      mainTextSwapTimerRef.current = null;
    }, CHYRON_SWAP_MS);
  }, [resolvedMainText, resolvedUseMarquee, displayMainText, displayUseMarquee]);

  useEffect(() => {
    if (resolvedCtaText === displayCtaText) {
      return;
    }

    if (ctaSwapTimerRef.current !== null) {
      window.clearTimeout(ctaSwapTimerRef.current);
      ctaSwapTimerRef.current = null;
    }

    setCtaActive(false);
    ctaSwapTimerRef.current = window.setTimeout(() => {
      setDisplayCtaText(resolvedCtaText);
      setCtaActive(true);
      ctaSwapTimerRef.current = null;
    }, CHYRON_SWAP_MS);
  }, [resolvedCtaText, displayCtaText]);

  useEffect(() => {
    return () => {
      if (mainTextSwapTimerRef.current !== null) {
        window.clearTimeout(mainTextSwapTimerRef.current);
        mainTextSwapTimerRef.current = null;
      }
      if (ctaSwapTimerRef.current !== null) {
        window.clearTimeout(ctaSwapTimerRef.current);
        ctaSwapTimerRef.current = null;
      }
      if (visibilityTimerRef.current !== null) {
        window.clearTimeout(visibilityTimerRef.current);
        visibilityTimerRef.current = null;
      }
      if (visibilityFrameRef.current !== null) {
        window.cancelAnimationFrame(visibilityFrameRef.current);
        visibilityFrameRef.current = null;
      }
    };
  }, []);

  if (!isMounted) {
    return null;
  }

  const wrapperStyle: React.CSSProperties = inline
    ? {
        width: '100%',
        opacity: isVisible ? 1 : 0,
        transform: isVisible ? 'translateY(0px)' : 'translateY(8px)',
        transition: `opacity ${CHYRON_SWAP_MS}ms ease, transform ${CHYRON_SWAP_MS}ms ease`
      }
    : {
