import { TooltipButton } from "./BleeckerButtons";
import React, { useEffect, useRef, useState } from 'react';
import type { ModoItalianoPodcastPlayerProps } from './ModoItalianoPodcastPlayer';

const THEME = {
  signal: '#ed0076',
  navy: '#0a1234',
  font: "'Barlow Condensed', 'Encode Sans', system-ui, sans-serif",
};

function timestamp(seconds: number) {
  const value = Number.isFinite(seconds) ? Math.max(0, Math.floor(seconds)) : 0;
  return `${Math.floor(value / 60)}:${String(value % 60).padStart(2, '0')}`;
}

/** Independent Giorgia presentation; the original podcast player remains unchanged. */
export function ModoItalianoGiorgiaPodcastPlayer({
  show = true, coverUrl = '', episodeTitle = '', showName = '', audioUrl = '', masterGain = 1,
}: ModoItalianoPodcastPlayerProps) {
  const audioRef = useRef<HTMLAudioElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const contextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [blocked, setBlocked] = useState(false);
  const [failed, setFailed] = useState(false);
  const [seekingFocused, setSeekingFocused] = useState(false);

  async function play() {
    const audio = audioRef.current;
    if (!audio || !audioUrl) return;
    try {
      if (!contextRef.current) {
        const context = new AudioContext();
        const analyser = context.createAnalyser();
        analyser.fftSize = 256;
        analyser.smoothingTimeConstant = 0.85;
        context.createMediaElementSource(audio).connect(analyser);
        analyser.connect(context.destination);
        contextRef.current = context;
        analyserRef.current = analyser;
      }
      await contextRef.current.resume();
      await audio.play();
      setBlocked(false);
    } catch {
      if (audio.error) setFailed(true);
      else setBlocked(true);
    }
  }

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;
    audio.volume = Number.isFinite(masterGain) ? Math.max(0, Math.min(1, masterGain)) : 0;
    audio.muted = masterGain <= 0.0001;
  }, [masterGain, show]);

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;
    audio.pause();
    setCurrentTime(0);
    setDuration(0);
    setBlocked(false);
    setFailed(false);
    audio.load();
    return () => audio.pause();
  }, [audioUrl, show]);

  useEffect(() => {
    if (!show) return;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!canvas || !ctx) return;
    const motion = window.matchMedia('(prefers-reduced-motion: reduce)');
    let frame = 0;
    const data = new Uint8Array(128);
    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = THEME.signal;
      const playing = audioRef.current && !audioRef.current.paused;
      if (playing && analyserRef.current && !motion.matches) {
        analyserRef.current.getByteFrequencyData(data);
        for (let i = 0; i < 80; i++) {
          const height = Math.max(2, (data[i] ?? 0) / 255 * 100);
          ctx.globalAlpha = 0.5 + height / 200;
          ctx.fillRect(i * 12, (120 - height) / 2, 5, height);
        }
      } else {
        ctx.globalAlpha = 0.5;
        ctx.fillRect(0, 59, canvas.width, 2);
      }
      frame = window.requestAnimationFrame(draw);
    };
    draw();
    return () => window.cancelAnimationFrame(frame);
  }, [show]);

  useEffect(() => () => {
    void contextRef.current?.close();
    contextRef.current = null;
    analyserRef.current = null;
  }, []);

  // Keep the audio node mounted so the analyser remains attached across visibility changes.
  return (
    <div hidden={!show} aria-label='Modo Italiano Giorgia podcast player' style={{
      position: 'absolute', inset: 0, overflow: 'hidden', color: '#fff', fontFamily: THEME.font,
      display: show ? 'flex' : 'none', alignItems: 'center', justifyContent: 'center',
    }}>
      {coverUrl && <img src={coverUrl} alt='Episode cover' style={{
        position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover',
        objectPosition: 'center center', filter: 'saturate(0.84) contrast(1.07)',
      }} />}
      <div aria-hidden='true' style={{ position: 'absolute', inset: 0,
        background: 'linear-gradient(180deg, rgba(10,18,52,0.48), rgba(10,18,52,0.04) 30%, rgba(10,18,52,0.66) 58%, rgba(10,18,52,0.98) 100%), linear-gradient(90deg, rgba(10,18,52,0.32), transparent 70%)',
      }} />
      <audio ref={audioRef} src={audioUrl || undefined} crossOrigin='anonymous' preload='metadata'
        onCanPlay={() => { if (show) void play(); }}
        onTimeUpdate={(event) => setCurrentTime(event.currentTarget.currentTime)}
        onDurationChange={(event) => setDuration(Number.isFinite(event.currentTarget.duration) ? event.currentTarget.duration : 0)}
        onError={() => setFailed(true)}
      />
      <section aria-label='Episode artwork and title' style={{ position: 'absolute', inset: 0 }}>
        <img src='/mi.svg' alt='ModoItaliano' style={{ position: 'absolute', top: '69px', left: '96px', width: '222px', height: 'auto', objectFit: 'contain', filter: 'brightness(0) invert(1) drop-shadow(0 15px 51px rgba(0,0,0,0.72))' }} />
        {!coverUrl && <p style={{ position: 'absolute', top: '180px', left: '110px', fontSize: '32px' }}>No cover selected</p>}
        <div style={{ position: 'absolute', left: '110px', right: '110px', bottom: '280px', paddingLeft: '44px', borderLeft: `10px solid ${THEME.signal}` }}>
            <p style={{ margin: '0 0 26px', fontFamily: THEME.font, fontSize: '34px', fontWeight: 600, color: '#fff',
              letterSpacing: '0.12em', textTransform: 'uppercase', overflowWrap: 'anywhere' }}>{showName}</p>
            <h1 style={{ margin: 0, maxWidth: '1560px', fontFamily: THEME.font, fontSize: episodeTitle.length > 90 ? '100px' : episodeTitle.length > 60 ? '124px' : '164px', lineHeight: 0.92,
              fontWeight: 700, letterSpacing: '-0.025em', textTransform: 'uppercase', textWrap: 'balance', overflowWrap: 'anywhere', whiteSpace: 'pre-wrap', textShadow: '0 8px 36px rgba(0,0,0,0.45)' }}>{episodeTitle}</h1>
        </div>
      </section>
      <div style={{ position: 'absolute', left: '110px', right: '110px', bottom: '64px', display: 'flex', flexDirection: 'column', gap: '18px' }}>
          <canvas ref={canvasRef} width={960} height={120} aria-hidden='true' style={{ width: '100%', height: '70px', display: 'block', opacity: 0.85 }} />
          <div style={{ position: 'relative', height: '20px', display: 'flex', alignItems: 'center', outline: seekingFocused ? '2px solid white' : 'none', outlineOffset: '5px' }}>
            <div aria-hidden='true' style={{ position: 'absolute', left: 0, right: 0, height: '3px', background: 'rgba(255,255,255,0.22)' }}>
              <div style={{ height: '100%', width: `${duration > 0 ? Math.min(100, currentTime / duration * 100) : 0}%`, background: THEME.signal }} />
            </div>
            <input aria-label='Episode progress' type='range' min={0} max={duration || 0} step={0.1}
              value={Math.min(currentTime, duration)} disabled={!duration}
              onFocus={() => setSeekingFocused(true)} onBlur={() => setSeekingFocused(false)}
              onChange={(event) => { if (audioRef.current) audioRef.current.currentTime = Number(event.target.value); }}
              style={{ position: 'relative', width: '100%', height: '20px', margin: 0, opacity: 0, cursor: 'pointer' }} />
          </div>
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '30px', fontVariantNumeric: 'tabular-nums', color: 'rgba(255,255,255,0.7)' }}>
            <span>{timestamp(currentTime)}</span><span>{timestamp(duration)}</span>
          </div>
          {failed ? <p role='alert' style={{ margin: 0, fontSize: '28px' }}>Unable to play this audio.</p>
            : blocked ? <TooltipButton onClick={() => void play()} style={{ alignSelf: 'flex-start', border: `1px solid ${THEME.signal}`, color: '#fff',
              background: THEME.navy, padding: '8px 18px', fontFamily: THEME.font, fontSize: '28px' }}>Start playback</TooltipButton> : null}
      </div>
    </div>
  );
}

export type ProgramSequenceMode = 'manual' | 'autoplay' | 'shuffle';
export type ProgramTextContentMode = 'text' | 'sequence';
export type ProgramSongContentMode = 'sequence';

interface BaseSequenceItem {
  id: string;
}

interface BaseSequence<TItem extends BaseSequenceItem> {
  mode: ProgramSequenceMode;
  items: TItem[];
  activeItemId?: string | null;
  intervalMs?: number;
  loop?: boolean;
  startedAt?: number;
}

type RecordValue = Record<string, unknown>;
const MAX_DEPTH = 8;

export interface ProgramTextSequenceLeafItem extends BaseSequenceItem {
  kind: 'preset';
  text: string;
  useMarquee?: boolean;
}

export interface ProgramTextSequenceNestedItem extends BaseSequenceItem {
  label: string;
  kind: 'sequence';
  sequence: ProgramTextSequence;
}

export type ProgramTextSequenceItem =
  | ProgramTextSequenceLeafItem
  | ProgramTextSequenceNestedItem;

export type ProgramTextSequence = BaseSequence<ProgramTextSequenceItem>;

export interface ProgramResolvedTextContent {
  text: string;
  useMarquee: boolean;
  source: ProgramTextContentMode;
  activePathLabels: string[];
}

export interface ProgramResolvedTextLeaf {
  text: string;
  useMarquee: boolean;
  activePathLabels: string[];
}

export interface ProgramSongSequenceLeafItem extends BaseSequenceItem {
  kind: 'preset';
  songId?: number;
  highRotation?: boolean;
  artist: string;
  title: string;
  coverUrl: string;
  audioUrl?: string;
  durationMs?: number;
  earoneSongId?: string;
  earoneRank?: string;
  earoneSpins?: string;
}

export interface ProgramSongSequenceNestedItem extends BaseSequenceItem {
  label: string;
  kind: 'sequence';
  sequence: ProgramSongSequence;
}

export type ProgramSongSequenceItem =
  | ProgramSongSequenceLeafItem
  | ProgramSongSequenceNestedItem;

export type ProgramSongSequence = BaseSequence<ProgramSongSequenceItem>;

export function shuffleProgramSongSequence(
  sequence: ProgramSongSequence,
  activeItemId: string | null = sequence.activeItemId ?? null,
  random: () => number = Math.random
): ProgramSongSequence {
  if (sequence.items.length < 2) return sequence;

  const anchoredItem = activeItemId
    ? sequence.items.find((item) => item.id === activeItemId) ?? null
    : null;
  const shuffledItems = anchoredItem
    ? sequence.items.filter((item) => item.id !== anchoredItem.id)
    : [...sequence.items];

  for (let index = shuffledItems.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.min(index, Math.max(0, Math.floor(random() * (index + 1))));
    [shuffledItems[index], shuffledItems[swapIndex]] = [shuffledItems[swapIndex], shuffledItems[index]];
  }

  const nextItems = anchoredItem ? [anchoredItem, ...shuffledItems] : shuffledItems;
  if (!nextItems.some((item, index) => item.id !== sequence.items[index]?.id) && shuffledItems.length > 1) {
    shuffledItems.push(shuffledItems.shift()!);
  }

  return {
    ...sequence,
    mode: 'shuffle',
    items: anchoredItem ? [anchoredItem, ...shuffledItems] : shuffledItems,
    activeItemId: anchoredItem?.id ?? sequence.activeItemId ?? nextItems[0]?.id ?? null
  };
}

export interface ProgramResolvedSongLeaf {
  id: string;
  songId?: number;
  highRotation: boolean;
  artist: string;
  title: string;
  coverUrl: string;
  audioUrl?: string;
  durationMs?: number;
  earoneSongId?: string;
  earoneRank?: string;
  earoneSpins?: string;
  activePathLabels: string[];
}

function asRecord(value: unknown): RecordValue | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return null;
  }
  return value as RecordValue;
}

function createId(prefix: string): string {
  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

function normalizeMode(value: unknown): ProgramSequenceMode {
  if (value === 'autoplay') return 'autoplay';
  if (value === 'shuffle') return 'shuffle';
  return 'manual';
}

function normalizeTextContentMode(
  contentMode: unknown,
  sequence: ProgramTextSequence | null
): ProgramTextContentMode {
  if (contentMode === 'text') {
    return 'text';
  }
  if (contentMode === 'sequence') {
    return 'sequence';
  }
  return sequence ? 'sequence' : 'text';
}

function normalizeSongContentMode(
  contentMode: unknown,
  sequence: ProgramSongSequence | null
): ProgramSongContentMode {
  return 'sequence';
}

function normalizeTextLeafItem(
  record: RecordValue,
  options?: { includeMarquee?: boolean }
): ProgramTextSequenceLeafItem {
  const text =
    typeof record.text === 'string' && record.text.trim()
      ? record.text
      : typeof record.label === 'string'
        ? record.label
        : '';

  return {
    id: typeof record.id === 'string' && record.id ? record.id : createId('preset'),
    kind: 'preset',
    text,
    useMarquee: options?.includeMarquee ? Boolean(record.useMarquee) : undefined
  };
}

function normalizeSongLeafItem(record: RecordValue): ProgramSongSequenceLeafItem {
  const artist =
    typeof record.artist === 'string' && record.artist.trim()
      ? record.artist.trim()
      : '';
  const title =
    typeof record.title === 'string' && record.title.trim()
      ? record.title.trim()
      : '';
  const coverUrl =
    typeof record.coverUrl === 'string' && record.coverUrl.trim()
      ? record.coverUrl.trim()
      : '';
  const audioUrl =
    typeof record.audioUrl === 'string' && record.audioUrl.trim()
      ? record.audioUrl.trim()
      : '';
  const durationMs =
    typeof record.durationMs === 'number' &&
    Number.isFinite(record.durationMs) &&
    record.durationMs > 0
      ? Math.round(record.durationMs)
      : undefined;

  return {
    id: typeof record.id === 'string' && record.id ? record.id : createId('song'),
    kind: 'preset',
    songId:
      typeof record.songId === 'number' && Number.isInteger(record.songId) && record.songId > 0
        ? record.songId
        : undefined,
    highRotation: record.highRotation === true,
    artist,
    title,
    coverUrl,
    audioUrl: audioUrl || undefined,
    durationMs,
    earoneSongId:
      typeof record.earoneSongId === 'string' && record.earoneSongId.trim()
        ? record.earoneSongId.trim()
        : typeof record.earoneSongId === 'number' && Number.isFinite(record.earoneSongId)
          ? String(record.earoneSongId)
          : undefined,
    earoneRank:
      typeof record.earoneRank === 'string' && record.earoneRank.trim()
        ? record.earoneRank.trim()
        : undefined,
    earoneSpins:
      typeof record.earoneSpins === 'string' && record.earoneSpins.trim()
        ? record.earoneSpins.trim()
        : typeof record.earoneSpins === 'number' && Number.isFinite(record.earoneSpins)
          ? String(record.earoneSpins)
          : undefined
  };
}

function withNormalizedSequenceShape<TItem extends BaseSequenceItem>(
  record: RecordValue,
  items: TItem[],
  defaultMode: ProgramSequenceMode = 'manual'
): BaseSequence<TItem> {
  const activeItemId =
    record.activeItemId === null
      ? null
      : typeof record.activeItemId === 'string' && items.some((item) => item.id === record.activeItemId)
      ? record.activeItemId
      : items[0]?.id ?? null;

  return {
    mode: record.mode === undefined ? defaultMode : normalizeMode(record.mode),
    items,
    activeItemId,
    intervalMs:
      typeof record.intervalMs === 'number' && Number.isFinite(record.intervalMs) && record.intervalMs >= 500
        ? Math.floor(record.intervalMs)
        : 4000,
    loop: record.loop === undefined ? true : Boolean(record.loop),
    startedAt:
      typeof record.startedAt === 'number' && Number.isFinite(record.startedAt)
        ? record.startedAt
        : Date.now()
  };
}

function normalizeTextSequenceItem(
  value: unknown,
  depth: number,
  options?: { includeMarquee?: boolean }
): ProgramTextSequenceItem | null {
  const record = asRecord(value);
  if (!record) {
    return null;
  }

  if (record.kind === 'sequence') {
    const normalizedSequence = normalizeProgramTextSequence(record.sequence, depth + 1, options);
    if (!normalizedSequence) {
      return null;
    }

    return {
      id: typeof record.id === 'string' && record.id ? record.id : createId('sequence'),
      label: typeof record.label === 'string' && record.label.trim() ? record.label : 'Nested Sequence',
      kind: 'sequence',
      sequence: normalizedSequence
    };
  }

  return normalizeTextLeafItem(record, options);
}

function normalizeSongSequenceItem(
  value: unknown,
  depth: number
): ProgramSongSequenceItem | null {
  const record = asRecord(value);
  if (!record) {
    return null;
  }

  if (record.kind === 'sequence') {
    const normalizedSequence = normalizeProgramSongSequence(record.sequence, depth + 1);
    if (!normalizedSequence) {
      return null;
    }

    return {
      id: typeof record.id === 'string' && record.id ? record.id : createId('sequence'),
      label: typeof record.label === 'string' && record.label.trim() ? record.label : 'Nested Sequence',
      kind: 'sequence',
      sequence: normalizedSequence
    };
  }

  return normalizeSongLeafItem(record);
}

function getBaseIndex<TItem extends BaseSequenceItem>(
  sequence: BaseSequence<TItem>
): number | null {
  if (sequence.activeItemId === null) {
    return null;
  }

  const activeIndex = sequence.items.findIndex((item) => item.id === sequence.activeItemId);
  return activeIndex >= 0 ? activeIndex : 0;
}

function getSelectedItem<TItem extends BaseSequenceItem>(
  sequence: BaseSequence<TItem>,
  nowMs: number
): TItem | null {
  if (sequence.items.length === 0) {
    return null;
  }

  const baseIndex = getBaseIndex(sequence);
  if (baseIndex === null) {
    return null;
  }

  if (sequence.mode === 'manual') {
    return sequence.items[baseIndex] ?? null;
  }

  const startedAt = sequence.startedAt ?? nowMs;
  const intervalMs = Math.max(500, sequence.intervalMs ?? 4000);
  const elapsedSteps = Math.max(0, Math.floor((nowMs - startedAt) / intervalMs));
  let nextIndex = baseIndex + elapsedSteps;

  if (sequence.loop !== false) {
    nextIndex %= sequence.items.length;
  } else if (nextIndex >= sequence.items.length) {
    nextIndex = sequence.items.length - 1;
  }

  return sequence.items[nextIndex] ?? null;
}

function getSongItemPlaybackDurationMs(
  item: ProgramSongSequenceItem
): number | null {
  if (
    item.kind === 'preset' &&
    typeof item.durationMs === 'number' &&
    Number.isFinite(item.durationMs) &&
    item.durationMs > 0
  ) {
    return Math.max(1, Math.round(item.durationMs));
  }

  return null;
}

function getSelectedSongItem(
  sequence: ProgramSongSequence,
  nowMs: number
): ProgramSongSequenceItem | null {
  if (sequence.items.length === 0) {
    return null;
  }

  const baseIndex = getBaseIndex(sequence);
  if (baseIndex === null) {
    return null;
  }

  if (sequence.mode === 'manual') {
    return sequence.items[baseIndex] ?? null;
  }

  const startedAt = sequence.startedAt ?? nowMs;
  const elapsedMs = Math.max(0, nowMs - startedAt);
  const itemDurations = sequence.items.map((item) => getSongItemPlaybackDurationMs(item));

  if (sequence.loop !== false) {
    const hasUnknownDuration = itemDurations.some((durationMs) => durationMs === null);
    if (!hasUnknownDuration) {
      const cycleDurationMs = itemDurations.reduce((sum, durationMs) => sum + (durationMs ?? 0), 0);
      if (cycleDurationMs <= 0) {
        return sequence.items[baseIndex] ?? null;
      }

      let remainingMs = elapsedMs % cycleDurationMs;
      for (let step = 0; step < sequence.items.length; step += 1) {
        const index = (baseIndex + step) % sequence.items.length;
        const itemDurationMs = itemDurations[index];
        if (typeof itemDurationMs !== 'number') {
          return sequence.items[index] ?? null;
        }
        if (remainingMs < itemDurationMs) {
          return sequence.items[index] ?? null;
        }
        remainingMs -= itemDurationMs;
      }

      return sequence.items[baseIndex] ?? null;
    }

    let remainingMs = elapsedMs;
    for (let step = 0; step < sequence.items.length; step += 1) {
      const index = (baseIndex + step) % sequence.items.length;
      const itemDurationMs = itemDurations[index];
      if (typeof itemDurationMs !== 'number') {
        return sequence.items[index] ?? null;
      }
      if (remainingMs < itemDurationMs) {
        return sequence.items[index] ?? null;
      }
      remainingMs -= itemDurationMs;
    }

    return sequence.items[baseIndex] ?? null;
  }

  let index = baseIndex;
  let remainingMs = elapsedMs;
  while (index < sequence.items.length - 1) {
    const itemDurationMs = itemDurations[index];
    if (typeof itemDurationMs !== 'number') {
      return sequence.items[index] ?? null;
    }
    if (remainingMs < itemDurationMs) {
      break;
    }
    remainingMs -= itemDurationMs;
    index += 1;
  }

  return sequence.items[index] ?? null;
}

function resolveTextSequenceRecursive(
  sequence: ProgramTextSequence,
  nowMs: number,
  depth: number,
  labels: string[]
): ProgramResolvedTextLeaf | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const selected = getSelectedItem(sequence, nowMs);
  if (!selected) {
    return null;
  }

  if (selected.kind === 'sequence') {
    const nextLabels = [...labels, selected.label];
    return resolveTextSequenceRecursive(selected.sequence, nowMs, depth + 1, nextLabels);
  }

  return {
    text: selected.text,
    useMarquee: Boolean(selected.useMarquee),
    activePathLabels: [...labels, selected.text]
  };
}

function resolveSongSequenceRecursive(
  sequence: ProgramSongSequence,
  nowMs: number,
  depth: number,
  labels: string[]
): ProgramResolvedSongLeaf | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const selected = getSelectedSongItem(sequence, nowMs);
  if (!selected) {
    return null;
  }

  if (selected.kind === 'sequence') {
    const nextLabels = [...labels, selected.label];
    return resolveSongSequenceRecursive(selected.sequence, nowMs, depth + 1, nextLabels);
  }

  const songLabel = [selected.artist, selected.title].filter(Boolean).join(' - ');
  return {
    id: selected.id,
    songId: selected.songId,
    highRotation: selected.highRotation === true,
    artist: selected.artist,
    title: selected.title,
    coverUrl: selected.coverUrl,
    audioUrl: selected.audioUrl,
    durationMs: selected.durationMs,
    earoneSongId: selected.earoneSongId,
    earoneRank: selected.earoneRank,
    earoneSpins: selected.earoneSpins,
    activePathLabels: [...labels, songLabel || 'Song Preset']
  };
}

export function normalizeProgramTextSequence(
  value: unknown,
  depth = 0,
  options?: { includeMarquee?: boolean }
): ProgramTextSequence | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const record = asRecord(value);
  if (!record) {
    return null;
  }

  const rawItems = Array.isArray(record.items) ? record.items : [];
  const items = rawItems
    .map((item) => normalizeTextSequenceItem(item, depth, options))
    .filter((item): item is ProgramTextSequenceItem => item !== null);

  return withNormalizedSequenceShape(record, items);
}

export function normalizeProgramSongSequence(
  value: unknown,
  depth = 0
): ProgramSongSequence | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const record = asRecord(value);
  if (!record) {
    return null;
  }

  const rawItems = Array.isArray(record.items) ? record.items : [];
  const items = rawItems
    .map((item) => normalizeSongSequenceItem(item, depth))
    .filter((item): item is ProgramSongSequenceItem => item !== null);

  return withNormalizedSequenceShape(record, items, 'autoplay');
}

export function createProgramTextSequenceItem(
  kind: ProgramTextSequenceItem['kind'] = 'preset',
  options?: { includeMarquee?: boolean }
): ProgramTextSequenceItem {
  if (kind === 'sequence') {
    return {
      id: createId('sequence'),
      label: 'Nested Sequence',
      kind: 'sequence',
      sequence: createProgramTextSequence('manual', options)
    };
  }

  return {
    id: createId('preset'),
    kind: 'preset',
    text: '',
    useMarquee: options?.includeMarquee ? false : undefined
  };
}

export function createProgramSongSequenceItem(
  kind: ProgramSongSequenceItem['kind'] = 'preset'
): ProgramSongSequenceItem {
  if (kind === 'sequence') {
    return {
      id: createId('sequence'),
      label: 'Nested Sequence',
      kind: 'sequence',
      sequence: createProgramSongSequence('manual')
    };
  }

  return {
    id: createId('song'),
    kind: 'preset',
    highRotation: false,
    artist: '',
    title: '',
    coverUrl: '',
    audioUrl: '',
    durationMs: undefined
  };
}

export function createProgramTextSequence(
  mode: ProgramSequenceMode = 'manual',
  options?: { includeMarquee?: boolean }
): ProgramTextSequence {
  const firstItem = createProgramTextSequenceItem('preset', options);

  return {
    mode,
    items: [firstItem],
    activeItemId: firstItem.id,
    intervalMs: 4000,
    loop: true,
    startedAt: Date.now()
  };
}

export function createProgramSongSequence(
  mode: ProgramSequenceMode = 'autoplay'
): ProgramSongSequence {
  return {
    mode,
    items: [],
    activeItemId: null,
    intervalMs: 4000,
    loop: true,
    startedAt: Date.now()
  };
}

export function getProgramTextContentMode(
  contentMode: unknown,
  sequence: ProgramTextSequence | null
): ProgramTextContentMode {
  return normalizeTextContentMode(contentMode, sequence);
}

export function getProgramSongContentMode(
  contentMode: unknown,
  sequence: ProgramSongSequence | null
): ProgramSongContentMode {
  return normalizeSongContentMode(contentMode, sequence);
}

export function getProgramTextSequenceSelectedItemId(
  sequence: ProgramTextSequence,
  nowMs = Date.now()
): string | null {
  return getSelectedItem(sequence, nowMs)?.id ?? null;
}

export function getProgramSongSequenceSelectedItemId(
  sequence: ProgramSongSequence,
  nowMs = Date.now()
): string | null {
  return getSelectedSongItem(sequence, nowMs)?.id ?? null;
}

export function resolveProgramTextContent(
  config: {
    text?: string;
    useMarquee?: boolean;
    contentMode?: unknown;
    sequence?: unknown;
  },
  nowMs = Date.now(),
  options?: { includeMarquee?: boolean }
): ProgramResolvedTextContent {
  const normalizedSequence = normalizeProgramTextSequence(config.sequence, 0, options);
  const contentMode = normalizeTextContentMode(config.contentMode, normalizedSequence);

  if (contentMode === 'sequence' && normalizedSequence) {
    const resolved = resolveTextSequenceRecursive(normalizedSequence, nowMs, 0, []);
    if (resolved) {
      return {
        text: resolved.text,
        useMarquee: resolved.useMarquee,
        source: 'sequence',
        activePathLabels: resolved.activePathLabels
      };
    }
  }

  return {
    text: typeof config.text === 'string' ? config.text : '',
    useMarquee: Boolean(config.useMarquee),
    source: 'text',
    activePathLabels: []
  };
}

export function resolveProgramTextLeaf(
  config: {
    contentMode?: unknown;
    sequence?: unknown;
  },
  nowMs = Date.now(),
  options?: { includeMarquee?: boolean }
): ProgramResolvedTextLeaf | null {
  const normalizedSequence = normalizeProgramTextSequence(config.sequence, 0, options);
  const contentMode = normalizeTextContentMode(config.contentMode, normalizedSequence);

  if (contentMode !== 'sequence' || !normalizedSequence) {
    return null;
  }

  return resolveTextSequenceRecursive(normalizedSequence, nowMs, 0, []);
}

export function resolveProgramSongLeaf(
  config: {
    contentMode?: unknown;
    sequence?: unknown;
  },
  nowMs = Date.now()
): ProgramResolvedSongLeaf | null {
  const normalizedSequence = normalizeProgramSongSequence(config.sequence);
  const contentMode = normalizeSongContentMode(config.contentMode, normalizedSequence);

  if (contentMode !== 'sequence' || !normalizedSequence) {
    return null;
  }

  return resolveSongSequenceRecursive(normalizedSequence, nowMs, 0, []);
}

export function countProgramTextSequenceLeafItems(
  sequence: ProgramTextSequence | null
): number {
  if (!sequence) {
    return 0;
  }

  return sequence.items.reduce((count, item) => {
    if (item.kind === 'sequence') {
      return count + countProgramTextSequenceLeafItems(item.sequence);
    }
    return count + 1;
  }, 0);
}

export function countProgramSongSequenceLeafItems(
  sequence: ProgramSongSequence | null
): number {
  if (!sequence) {
    return 0;
  }

  return sequence.items.reduce((count, item) => {
    if (item.kind === 'sequence') {
      return count + countProgramSongSequenceLeafItems(item.sequence);
    }
    return count + 1;
  }, 0);
}

import { interpolateGainLog } from './audioTaper';
import { apiUrl } from './apiBaseUrl';

export interface ProgramAudioBusTrack {
  token: string;
  audioUrl: string;
  durationMs?: number;
  artist?: string;
  title?: string;
  coverUrl?: string;
  earoneSongId?: string;
  earoneRank?: string;
  earoneSpins?: string;
}

export interface ProgramAudioBusSnapshot {
  track: ProgramAudioBusTrack | null;
  progress: number;
  currentTimeMs: number;
  durationMs: number | null;
  endedToken: string;
  isPlaying: boolean;
}

export interface ProgramAudioBusSignalSnapshot {
  rms: number;
  peak: number;
}

type Listener = (snapshot: ProgramAudioBusSnapshot) => void;

interface MeterEnvelope {
  stepMs: number;
  values: Float32Array;
}

interface ProgramAudioBusState {
  activeTrack: ProgramAudioBusTrack | null;
  activeAudio: HTMLAudioElement | null;
  masterVolume: number;
  progress: number;
  endedToken: string;
  isPlaying: boolean;
  transitionVersion: number;
  listeners: Set<Listener>;
  meterContext: AudioContext | null;
  meterSource: AudioNode | null;
  meterAnalyser: AnalyserNode | null;
  meterBuffer: Float32Array | null;
  lastSignalLevel: number;
  meterUsesMediaElementFallback: boolean;
  meterEnvelopeUrl: string;
  meterEnvelope: MeterEnvelope | null;
}

const audioBusByProgram = new Map<string, ProgramAudioBusState>();
const meterEnvelopeByUrl = new Map<string, Promise<MeterEnvelope | null>>();
const AUDIO_FADE_OUT_MS = 420;
const AUDIO_FADE_IN_MS = 320;
const AUDIO_FADE_STEP_MS = 20;
const AUDIO_TARGET_VOLUME = 1;
const METER_ENVELOPE_FRAME_MS = 24;
const METER_ENVELOPE_LOW_PERCENTILE = 0.12;
const METER_ENVELOPE_HIGH_PERCENTILE = 0.985;
const METER_ENVELOPE_TOP_EXPAND_POWER = 1.6;
const METER_ATTACK_COEFFICIENT = 0.45;
const METER_RELEASE_COEFFICIENT = 0.2;

function createProgramAudioBusState(): ProgramAudioBusState {
  return {
    activeTrack: null,
    activeAudio: null,
    masterVolume: 1,
    progress: 0,
    endedToken: '',
    isPlaying: false,
    transitionVersion: 0,
    listeners: new Set<Listener>(),
    meterContext: null,
    meterSource: null,
    meterAnalyser: null,
    meterBuffer: null,
    lastSignalLevel: 0,
    meterUsesMediaElementFallback: false,
    meterEnvelopeUrl: '',
    meterEnvelope: null
  };
}

function normalizeProgramId(programId: string): string {
  return typeof programId === 'string' ? programId.trim() : '';
}

function getProgramAudioBusState(programId: string, createIfMissing: boolean): ProgramAudioBusState | null {
  const normalizedProgramId = normalizeProgramId(programId);
  if (!normalizedProgramId) {
    return null;
  }

  const existing = audioBusByProgram.get(normalizedProgramId);
  if (existing) {
    return existing;
  }

  if (!createIfMissing) {
    return null;
  }

  const created = createProgramAudioBusState();
  audioBusByProgram.set(normalizedProgramId, created);
  return created;
}

function clampProgress(value: number): number {
  if (!Number.isFinite(value)) {
    return 0;
  }
  return Math.max(0, Math.min(1, value));
}

function clampVolume(value: number): number {
  if (!Number.isFinite(value)) {
    return AUDIO_TARGET_VOLUME;
  }
  return Math.max(0, Math.min(AUDIO_TARGET_VOLUME, value));
}

function getAudioProgress(audio: HTMLAudioElement): number {
  const duration = Number(audio.duration);
  if (!Number.isFinite(duration) || duration <= 0) {
    return 0;
  }
  return clampProgress(audio.currentTime / duration);
}

function getSnapshot(state: ProgramAudioBusState): ProgramAudioBusSnapshot {
  const hasTrack = Boolean(state.activeTrack);
  const durationSeconds = state.activeAudio ? Number(state.activeAudio.duration) : Number.NaN;
  const derivedDurationMs = Number.isFinite(durationSeconds) && durationSeconds > 0 ? Math.round(durationSeconds * 1000) : null;
  const durationMs =
    derivedDurationMs ??
    (typeof state.activeTrack?.durationMs === 'number' && Number.isFinite(state.activeTrack.durationMs) && state.activeTrack.durationMs > 0
      ? Math.round(state.activeTrack.durationMs)
      : null);
  const currentSeconds = state.activeAudio ? Number(state.activeAudio.currentTime) : Number.NaN;
  let currentTimeMs = Number.isFinite(currentSeconds) && currentSeconds >= 0 ? Math.round(currentSeconds * 1000) : 0;
  if (durationMs !== null) {
    currentTimeMs = Math.max(0, Math.min(currentTimeMs, durationMs));
  }

  return {
    track: state.activeTrack,
    progress: state.progress,
    currentTimeMs: hasTrack ? currentTimeMs : 0,
    durationMs: hasTrack ? durationMs : null,
    endedToken: state.endedToken,
    isPlaying: state.isPlaying
  };
}

function emit(state: ProgramAudioBusState): void {
  const snapshot = getSnapshot(state);
  state.listeners.forEach((listener) => {
    listener(snapshot);
  });
}

function clearAudioBindings(audio: HTMLAudioElement): void {
  audio.onplay = null;
  audio.onpause = null;
  audio.ontimeupdate = null;
  audio.onloadedmetadata = null;
  audio.onended = null;
  audio.onerror = null;
}

function releaseAudioMeter(state: ProgramAudioBusState): void {
  if (state.meterUsesMediaElementFallback && state.activeAudio) {
    state.activeAudio.muted = false;
  }
  if (state.meterSource) {
    try {
      state.meterSource.disconnect();
    } catch {
      // no-op
    }
    state.meterSource = null;
  }
  if (state.meterAnalyser) {
    try {
      state.meterAnalyser.disconnect();
    } catch {
      // no-op
    }
    state.meterAnalyser = null;
  }
  state.meterBuffer = null;
  state.lastSignalLevel = 0;
  state.meterUsesMediaElementFallback = false;
}

function setupAudioMeter(state: ProgramAudioBusState, audio: HTMLAudioElement): void {
  releaseAudioMeter(state);
  if (typeof window === 'undefined') {
    return;
  }

  const AudioContextCtor = window.AudioContext || (window as typeof window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
  if (!AudioContextCtor) {
    return;
  }

  try {
    const context = state.meterContext ?? new AudioContextCtor();
    state.meterContext = context;
    const attachFromStream = (): boolean => {
      const stream =
        audio.captureStream?.() ||
        (audio as HTMLAudioElement & { mozCaptureStream?: () => MediaStream }).mozCaptureStream?.();
      if (!stream) {
        return false;
      }

      const source = context.createMediaStreamSource(stream);
      const analyser = context.createAnalyser();
      analyser.fftSize = 1024;
      analyser.smoothingTimeConstant = 0.78;
      source.connect(analyser);
      state.meterSource = source;
      state.meterAnalyser = analyser;
      state.meterBuffer = new Float32Array(analyser.fftSize);
      state.meterUsesMediaElementFallback = false;
      return true;
    };

    const attachFromMediaElement = (): boolean => {
      if (context.state !== 'running') {
        return false;
      }
      const source = context.createMediaElementSource(audio);
      const analyser = context.createAnalyser();
      analyser.fftSize = 1024;
      analyser.smoothingTimeConstant = 0.78;
      source.connect(analyser);
      source.connect(context.destination);
      audio.muted = true;
      state.meterSource = source;
      state.meterAnalyser = analyser;
      state.meterBuffer = new Float32Array(analyser.fftSize);
      state.meterUsesMediaElementFallback = true;
      return true;
    };

    if (attachFromStream()) {
      if (context.state === 'suspended') {
        void context.resume().catch(() => {
          // ignore resume failures; meter can recover on next track
        });
      }
      return;
    }

    if (attachFromMediaElement()) {
      return;
    }

    if (context.state === 'suspended') {
      void context
        .resume()
        .then(() => {
          if (state.activeAudio !== audio || state.meterSource) {
            return;
          }
          try {
            void attachFromMediaElement();
          } catch {
            // no-op
          }
        })
        .catch(() => {
          // ignore resume failures; some environments require user gesture
        });
    }
  } catch {
    releaseAudioMeter(state);
  }
}

function getAudioContextConstructor():
  | typeof AudioContext
  | undefined {
  if (typeof window === 'undefined') {
    return undefined;
  }
  return (
    window.AudioContext ||
    (window as typeof window & { webkitAudioContext?: typeof AudioContext })
      .webkitAudioContext
  );
}

function buildMeterEnvelope(audioBuffer: AudioBuffer): MeterEnvelope | null {
  const { numberOfChannels, length, sampleRate } = audioBuffer;
  if (numberOfChannels <= 0 || length <= 0 || !Number.isFinite(sampleRate) || sampleRate <= 0) {
    return null;
  }

  const frameSize = Math.max(256, Math.round((sampleRate * METER_ENVELOPE_FRAME_MS) / 1000));
  const frameCount = Math.max(1, Math.ceil(length / frameSize));
  const values = new Float32Array(frameCount);

  for (let frameIndex = 0; frameIndex < frameCount; frameIndex += 1) {
    const start = frameIndex * frameSize;
    const end = Math.min(length, start + frameSize);
    const sampleCount = Math.max(1, end - start);
    let peakChannelRms = 0;

    for (let channelIndex = 0; channelIndex < numberOfChannels; channelIndex += 1) {
      const channelData = audioBuffer.getChannelData(channelIndex);
      let sumSquares = 0;
      for (let sampleIndex = start; sampleIndex < end; sampleIndex += 1) {
        const sample = channelData[sampleIndex];
        sumSquares += sample * sample;
      }
      const rms = Math.sqrt(sumSquares / sampleCount);
      if (rms > peakChannelRms) {
        peakChannelRms = rms;
      }
    }

    values[frameIndex] = peakChannelRms;
  }

  if (values.length === 0) {
    return {
      stepMs: frameSize * 1000 / sampleRate,
      values
    };
  }

  const sortedValues = Array.from(values).sort((left, right) => left - right);
  const lowIndex = Math.max(0, Math.min(sortedValues.length - 1, Math.floor(sortedValues.length * METER_ENVELOPE_LOW_PERCENTILE)));
  const highIndex = Math.max(lowIndex, Math.min(sortedValues.length - 1, Math.floor(sortedValues.length * METER_ENVELOPE_HIGH_PERCENTILE)));
  const floorValue = sortedValues[lowIndex] ?? 0;
  const ceilingValue = Math.max(floorValue + 1e-6, sortedValues[highIndex] ?? floorValue + 1e-6);
  let previousNormalized = 0;

  // Normalize using percentiles and add transient emphasis for visible movement.
  for (let index = 0; index < values.length; index += 1) {
    const normalized = Math.max(0, Math.min(1, (values[index] - floorValue) / (ceilingValue - floorValue)));
    const topExpanded = Math.pow(normalized, METER_ENVELOPE_TOP_EXPAND_POWER);
    const transient = Math.max(0, topExpanded - previousNormalized * 0.94);
    const emphasized = Math.max(0, Math.min(1, topExpanded * 0.8 + transient * 1.25));
    values[index] = emphasized;
    previousNormalized = emphasized;
  }

  return {
    stepMs: frameSize * 1000 / sampleRate,
    values
  };
}

function getMeterEnvelope(audioUrl: string, context: AudioContext): Promise<MeterEnvelope | null> {
  const existing = meterEnvelopeByUrl.get(audioUrl);
  if (existing) {
    return existing;
  }

  const promise = (async () => {
    try {
      const response = await fetch(resolveEnvelopeFetchUrl(audioUrl));
      if (!response.ok) {
        return null;
      }
      const arrayBuffer = await response.arrayBuffer();
      const decoded = await context.decodeAudioData(arrayBuffer.slice(0));
      return buildMeterEnvelope(decoded);
    } catch {
      return null;
    }
  })();

  meterEnvelopeByUrl.set(audioUrl, promise);
  return promise;
}

function resolveEnvelopeFetchUrl(audioUrl: string): string {
  const normalized = audioUrl.trim();
  if (!normalized) {
    return normalized;
  }

  try {
    const parsed = new URL(normalized, window.location.href);
    if (parsed.origin === window.location.origin) {
      return parsed.toString();
    }
    return apiUrl(`/program/audio-proxy?url=${encodeURIComponent(parsed.toString())}`);
  } catch {
    return apiUrl(`/program/audio-proxy?url=${encodeURIComponent(normalized)}`);
  }
}

function setupAudioMeterEnvelope(state: ProgramAudioBusState, trackAudioUrl: string): void {
  const normalizedUrl = typeof trackAudioUrl === 'string' ? trackAudioUrl.trim() : '';
  state.meterEnvelopeUrl = normalizedUrl;
  state.meterEnvelope = null;
  if (!normalizedUrl) {
    return;
  }

  const AudioContextCtor = getAudioContextConstructor();
  if (!AudioContextCtor) {
    return;
  }
  const context = state.meterContext ?? new AudioContextCtor();
  state.meterContext = context;

  void getMeterEnvelope(normalizedUrl, context).then((envelope) => {
    if (state.meterEnvelopeUrl !== normalizedUrl) {
      return;
    }
    state.meterEnvelope = envelope;
  });
}

function detachAndStopAudio(audio: HTMLAudioElement): void {
  clearAudioBindings(audio);
  audio.pause();
  try {
    audio.currentTime = 0;
  } catch {
    // no-op
  }
}

function fadeAudioVolume(
  audio: HTMLAudioElement,
  from: number,
  to: number,
  durationMs: number,
  shouldContinue: () => boolean
): Promise<void> {
  const normalizedFrom = clampVolume(from);
  const normalizedTo = clampVolume(to);
  audio.volume = normalizedFrom;

  if (durationMs <= 0 || normalizedFrom === normalizedTo) {
    audio.volume = normalizedTo;
    return Promise.resolve();
  }

  const steps = Math.max(1, Math.round(durationMs / AUDIO_FADE_STEP_MS));
  return new Promise((resolve) => {
    let step = 0;
    const timer = window.setInterval(() => {
      if (!shouldContinue()) {
        window.clearInterval(timer);
        resolve();
        return;
      }

      step += 1;
      const ratio = Math.min(1, step / steps);
      audio.volume = clampVolume(interpolateGainLog(normalizedFrom, normalizedTo, ratio));

      if (ratio >= 1) {
        window.clearInterval(timer);
        resolve();
      }
    }, AUDIO_FADE_STEP_MS);
  });
}

function setActiveAudio(state: ProgramAudioBusState, audio: HTMLAudioElement, trackToken: string, trackAudioUrl: string): void {
  audio.preload = 'auto';
  setupAudioMeter(state, audio);
  setupAudioMeterEnvelope(state, trackAudioUrl);

  audio.onplay = () => {
    state.isPlaying = true;
    emit(state);
  };

  audio.onpause = () => {
    if (!audio.ended) {
      state.isPlaying = false;
      emit(state);
    }
  };

  audio.onloadedmetadata = () => {
    state.progress = getAudioProgress(audio);
    emit(state);
  };

  audio.ontimeupdate = () => {
    state.progress = getAudioProgress(audio);
    emit(state);
  };

  audio.onended = () => {
    state.progress = 1;
    state.isPlaying = false;
    state.endedToken = trackToken;
    emit(state);
  };

  audio.onerror = () => {
    state.isPlaying = false;
    emit(state);
  };

  state.activeAudio = audio;
}

function replaceTrack(state: ProgramAudioBusState, track: ProgramAudioBusTrack): void {
  if (state.activeAudio) {
    releaseAudioMeter(state);
    detachAndStopAudio(state.activeAudio);
    state.activeAudio = null;
  }

  state.activeTrack = track;
  state.progress = 0;
  state.endedToken = '';
  state.isPlaying = false;

  const audio = new Audio(track.audioUrl);
  audio.volume = clampVolume(state.masterVolume);
  setActiveAudio(state, audio, track.token, track.audioUrl);
  emit(state);

  const playPromise = audio.play();
  if (playPromise && typeof playPromise.catch === 'function') {
    playPromise.catch((err) => {
      console.error(`Failed to start audio bus track "${track.audioUrl}"`, err);
      state.isPlaying = false;
      emit(state);
    });
  }
}

async function transitionToTrackWithFade(state: ProgramAudioBusState, track: ProgramAudioBusTrack): Promise<void> {
  state.transitionVersion += 1;
  const version = state.transitionVersion;
  const outgoingAudio = state.activeAudio;

  if (outgoingAudio && !outgoingAudio.ended) {
    const startVolume = clampVolume(outgoingAudio.volume);
    await fadeAudioVolume(outgoingAudio, startVolume, 0, AUDIO_FADE_OUT_MS, () => version === state.transitionVersion);
  }

  if (version !== state.transitionVersion) {
    return;
  }

  if (outgoingAudio) {
    releaseAudioMeter(state);
    detachAndStopAudio(outgoingAudio);
    if (state.activeAudio === outgoingAudio) {
      state.activeAudio = null;
    }
  }

  state.activeTrack = track;
  state.progress = 0;
  state.endedToken = '';
  state.isPlaying = false;

  const incomingAudio = new Audio(track.audioUrl);
  incomingAudio.volume = 0;
  setActiveAudio(state, incomingAudio, track.token, track.audioUrl);
  emit(state);

  try {
    const playPromise = incomingAudio.play();
    if (playPromise && typeof playPromise.catch === 'function') {
      await playPromise;
    }
  } catch (err) {
    console.error(`Failed to start audio bus track "${track.audioUrl}"`, err);
    state.isPlaying = false;
    emit(state);
    return;
  }

  if (version !== state.transitionVersion) {
    return;
  }

  const targetVolume = clampVolume(state.masterVolume);
  await fadeAudioVolume(incomingAudio, incomingAudio.volume, targetVolume, AUDIO_FADE_IN_MS, () => version === state.transitionVersion);

  if (version !== state.transitionVersion) {
    return;
  }
  incomingAudio.volume = targetVolume;
}

export function ensureProgramAudioBusTrack(programId: string, track: ProgramAudioBusTrack): void {
  const state = getProgramAudioBusState(programId, true);
  if (!state) {
    return;
  }

  const normalizedToken = track.token.trim();
  const normalizedUrl = track.audioUrl.trim();
  if (!normalizedToken || !normalizedUrl) {
    return;
  }

  const normalizedTrack: ProgramAudioBusTrack = {
    ...track,
    token: normalizedToken,
    audioUrl: normalizedUrl
  };

  if (state.activeTrack && state.activeTrack.token === normalizedTrack.token && state.activeAudio) {
    if (state.activeAudio.ended) {
      state.activeAudio.currentTime = 0;
      state.endedToken = '';
      state.progress = 0;
      state.isPlaying = false;
    }
    if (state.activeAudio.paused) {
      const playPromise = state.activeAudio.play();
      if (playPromise && typeof playPromise.catch === 'function') {
        playPromise.catch(() => {
          // keep existing track state; no hard failure for autoplay restrictions
        });
      }
    }
    emit(state);
    return;
  }

  const hasRunningTrack = state.activeTrack && state.activeAudio && !state.activeAudio.ended && !state.activeAudio.paused;
  if (hasRunningTrack) {
    void transitionToTrackWithFade(state, normalizedTrack);
    return;
  }

  state.transitionVersion += 1;
  replaceTrack(state, normalizedTrack);
}

export function stopProgramAudioBus(programId: string): void {
  const state = getProgramAudioBusState(programId, false);
  if (!state) {
    return;
  }

  state.transitionVersion += 1;

  if (state.activeAudio) {
    releaseAudioMeter(state);
    detachAndStopAudio(state.activeAudio);
    state.activeAudio = null;
  }

  state.activeTrack = null;
  state.progress = 0;
  state.endedToken = '';
  state.isPlaying = false;
  state.meterEnvelopeUrl = '';
  state.meterEnvelope = null;
  emit(state);
}

export function setProgramAudioBusMasterVolume(programId: string, volume: number): void {
  const state = getProgramAudioBusState(programId, true);
  if (!state) {
    return;
  }

  const normalizedVolume = clampVolume(volume);
  state.masterVolume = normalizedVolume;

  if (state.activeAudio) {
    state.activeAudio.volume = normalizedVolume;
  }

  emit(state);
}

export function getProgramAudioBusSnapshot(programId: string): ProgramAudioBusSnapshot {
  const state = getProgramAudioBusState(programId, false);
  if (!state) {
    return {
      track: null,
      progress: 0,
      currentTimeMs: 0,
      durationMs: null,
      endedToken: '',
      isPlaying: false
    };
  }

  return getSnapshot(state);
}

export function getProgramAudioBusSignalLevel(programId: string): number {
  const snapshot = getProgramAudioBusSignalSnapshot(programId);
  const state = getProgramAudioBusState(programId, false);
  if (!state) {
    return 0;
  }

  const coefficient = snapshot.rms >= state.lastSignalLevel ? METER_ATTACK_COEFFICIENT : METER_RELEASE_COEFFICIENT;
  const smoothed = state.lastSignalLevel + (snapshot.rms - state.lastSignalLevel) * coefficient;
  state.lastSignalLevel = smoothed;
  return Math.max(0, Math.min(1, smoothed));
}

export function getProgramAudioBusSignalSnapshot(programId: string): ProgramAudioBusSignalSnapshot {
  const state = getProgramAudioBusState(programId, false);
  if (!state || !state.activeAudio || state.activeAudio.paused || state.activeAudio.ended) {
    if (state) {
      state.lastSignalLevel = 0;
    }
    return {
      rms: 0,
      peak: 0
    };
  }
  let nextRms = 0;
  let nextPeak = 0;
  if (state.meterAnalyser && state.meterBuffer) {
    state.meterAnalyser.getFloatTimeDomainData(state.meterBuffer);
    let sumSquares = 0;
    let peakSample = 0;
    for (let index = 0; index < state.meterBuffer.length; index += 1) {
      const sample = state.meterBuffer[index];
      sumSquares += sample * sample;
      const absSample = Math.abs(sample);
      if (absSample > peakSample) {
        peakSample = absSample;
      }
    }
    nextRms = Math.sqrt(sumSquares / state.meterBuffer.length);
    nextPeak = peakSample;
  } else if (
    state.meterEnvelope &&
    state.meterEnvelope.values.length > 0 &&
    Number.isFinite(state.activeAudio.currentTime)
  ) {
    const timeMs = Math.max(0, state.activeAudio.currentTime * 1000);
    const envelopeIndex = Math.max(
      0,
      Math.min(
        state.meterEnvelope.values.length - 1,
      Math.floor(timeMs / Math.max(1, state.meterEnvelope.stepMs))
      )
    );
    const envelopeLevel = state.meterEnvelope.values[envelopeIndex] ?? 0;
    const normalizedEnvelopeLevel = envelopeLevel * clampVolume(state.activeAudio.volume);
    nextRms = normalizedEnvelopeLevel;
    nextPeak = normalizedEnvelopeLevel;
  } else {
    // Fallback when analyser capture is unavailable (e.g. restricted embeds):
    // report post-fader output level so control still reflects live gain changes.
    const volume = clampVolume(state.activeAudio.volume);
    nextRms = volume;
    nextPeak = volume;
  }

  return {
    rms: Math.max(0, Math.min(1, nextRms)),
    peak: Math.max(0, Math.min(1, nextPeak))
  };
}

export function subscribeProgramAudioBus(programId: string, listener: Listener): () => void {
  const state = getProgramAudioBusState(programId, true);
  if (!state) {
    listener({
      track: null,
      progress: 0,
      currentTimeMs: 0,
      durationMs: null,
      endedToken: '',
      isPlaying: false
    });
    return () => {
      // no-op
    };
  }

  state.listeners.add(listener);
  listener(getSnapshot(state));
  return () => {
    state.listeners.delete(listener);
  };
}

