  const state = getProgramAudioBusState(programId, true);
  if (!state) {
    listener({
      track: null,
      progress: 0,
      currentTimeMs: 0,
      durationMs: null,
      endedToken: '',
      isPlaying: false
    });
    return () => {
      // no-op
